  color: #1d1d1f;
}

.tile-warm .tile-tagline {
  color: #6e6e73;
}

.tile-cool {
  background: linear-gradient(135deg, #e8f0fe, #d4e4fc);
  color: #1d1d1f;
}

.tile-cool .tile-tagline {
  color: #6e6e73;
}

.tile-green {
  background: linear-gradient(135deg, #e8f5e9, #c8e6c9);
  color: #1d1d1f;
}

.tile-green .tile-tagline {
  color: #4e6e50;
}

.tile-green .tile-ctas a {
  color: #1b5e20;
}

.tile-purple {
  background: linear-gradient(135deg, #f3e5f5, #e1bee7);
  color: #1d1d1f;
}

.tile-purple .tile-tagline {
  color: #6e6e73;
}

/* ========== ENTERTAINMENT TABS ========== */
.entertainment-section {
  padding: 80px 0;
  background: var(--color-bg);
}

.entertainment-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.entertainment-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}

.entertainment-tab {
  padding: 10px 24px;
  border-radius: 980px;
  border: none;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  font-family: var(--font-sans);
}

.entertainment-tab:hover {
  background: var(--color-border);
}

.entertainment-tab.active {
  background: var(--color-text);
  color: var(--color-bg);
}

.entertainment-content {
  display: none;
}

.entertainment-content.active {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.entertainment-card {
  background: var(--color-bg-secondary);
  border-radius: 16px;
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}

.entertainment-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
}

.entertainment-card-visual {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}

.entertainment-card-body {
  padding: 16px;
}

.entertainment-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
}

.entertainment-card-body p {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.entertainment-card-body a {
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.entertainment-card-body a::after {
  content: '›';
  font-size: 16px;
}

/* Entertainment card color themes */
.ent-streaming { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.ent-fitness { background: linear-gradient(135deg, #0f4c3a, #1a6b4f); }
.ent-gaming { background: linear-gradient(135deg, #2d1b69, #4a2c8e); }
.ent-music { background: linear-gradient(135deg, #8e1537, #c0392b); }

/* ========== HELP / SUPPORT CARDS ========== */
.help-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 32px 24px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition), box-shadow var(--transition);
}

.help-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
}

.help-card .help-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 16px;
  background: var(--color-bg-secondary);
}

.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.help-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== STORE DIFFERENCE ========== */
.diff-card {
  flex: 0 0 240px;
  text-align: center;
  padding: 32px 20px;
  background: var(--color-bg);
  border-radius: 20px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition);
}

.diff-card:hover {
  transform: translateY(-2px);
}

.diff-card .diff-icon {
  font-size: 36px;
  margin-bottom: 16px;
}

.diff-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.diff-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== BRAND COLLAB ========== */
.brand-collab {
  padding: 80px 0;
  background: linear-gradient(135deg, #1d1d1f, #2c2c2e);
  color: #f5f5f7;
  text-align: center;
}

.brand-collab h2 {
  font-family: var(--font-display);
  font-size: 40px;
  font-weight: 700;
  margin-bottom: 8px;
}

.brand-collab p {
  font-size: 18px;
  color: #a1a1a6;
  margin-bottom: 24px;
}

.brand-collab .collab-items {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.collab-chip {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 980px;
  padding: 10px 24px;
  font-size: 14px;
  color: #f5f5f7;
}

/* ========== QUICK LINKS ========== */
.quick-links {
  padding: 40px 0;
  background: var(--color-bg);
}

.quick-links-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 12px 24px;
  border-radius: 980px;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  transition: background var(--transition);
}

.quick-link:hover {
  background: var(--color-border);
  text-decoration: none;
  color: var(--color-text);
}

.quick-link::after {
  content: '›';
  font-size: 16px;
  opacity: 0.5;
}

/* ========== CATEGORY PAGE HERO ========== */
.category-hero {
  text-align: center;
  padding: 60px 24px 0;
}

.category-hero h1 {
  font-family: var(--font-display);
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
}

.category-hero .subtitle {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 8px;
}

/* ========== STICKY SECTION NAV ========== */
.section-nav {
  position: sticky;
  top: 52px;
  z-index: 100;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  padding: 0 24px;
  margin-top: 24px;
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: 32px;
  overflow-x: auto;
  scrollbar-width: none;
}

.section-nav-inner::-webkit-scrollbar {
  display: none;
}

.section-nav-link {
  flex-shrink: 0;
  padding: 14px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}

.section-nav-link:hover {
  color: var(--color-text);
  text-decoration: none;
}

.section-nav-link.active {
  color: var(--color-text);
  border-bottom-color: var(--color-text);
}

/* ========== GUIDES / SAVINGS GRID ========== */
.guides-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.guide-card {
  background: var(--color-bg);
  border-radius: 20px;
  padding: 32px 24px;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition), box-shadow var(--transition);
}

.guide-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.06);
}

.guide-card .guide-icon {
  font-size: 32px;
  margin-bottom: 16px;
}

.guide-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.guide-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== FOOTER ========== */
.site-footer {
  background: var(--color-bg-secondary);
  padding: 40px 0 24px;
  border-top: 1px solid var(--color-border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  margin-bottom: 40px;
}

.footer-column h4 {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--color-text);
  cursor: default;
}

.footer-column ul {
  list-style: none;
}

.footer-column li {
  margin-bottom: 6px;
}

.footer-column a {
  font-size: 12px;
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-column a:hover {
  color: var(--color-text);
}

.footer-legal {
  border-top: 1px solid var(--color-border);
  padding-top: 20px;
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.footer-legal p {
  margin-bottom: 8px;
}

.footer-bottom-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 12px;
  flex-wrap: wrap;
  gap: 8px;
}

.footer-bottom-row .copyright {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.footer-bottom-links {
  display: flex;
  gap: 16px;
}

.footer-bottom-links a {
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* ========== SAVINGS CARDS (Carousel) ========== */
.savings-card {
  flex: 0 0 260px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition);
}

.savings-card:hover {
  transform: translateY(-2px);
}

.savings-card .savings-icon {
  font-size: 32px;
  margin-bottom: 16px;
}

.savings-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.savings-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== SPECIAL STORES ========== */
.special-stores-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.special-store-card {
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform var(--transition);
}

.special-store-card:hover { transform: translateY(-2px); }

.special-store-card .store-icon {
  font-size: 28px;
  margin-bottom: 12px;
}

.special-store-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}

.special-store-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .product-grid-inner {
    grid-template-columns: 1fr;
  }

  .entertainment-content.active {
    grid-template-columns: repeat(2, 1fr);
  }

  .section-header h2 {
    font-size: 36px;
  }

  .store-hero h1,
  .category-hero h1 {
    font-size: 44px;
  }

  .carousel-header h2 {
    font-size: 32px;
  }
}

@media (max-width: 768px) {
  body {
    font-size: 15px;
  }

  .nav-links {
    display: none;
  }

  .nav-hamburger {
    display: block;
  }

  .section-header h2 {
    font-size: 28px;
  }

  .section-header p {
    font-size: 17px;
  }

  .store-hero h1,
  .category-hero h1 {
    font-size: 36px;
  }

  .store-hero .subtitle,
  .category-hero .subtitle {
    font-size: 18px;
  }

  .carousel-header h2 {
    font-size: 26px;
  }

  .product-card {
    flex: 0 0 240px;
  }

  .product-tile {
    min-height: 380px;
    padding: 36px 28px 28px;
  }

  .product-tile h3 {
    font-size: 28px;
  }

  .product-tile .tile-tagline {
    font-size: 16px;
  }

  .entertainment-content.active {
    grid-template-columns: 1fr 1fr;
  }

  .footer-columns {
    grid-template-columns: 1fr 1fr;
  }

  /* Footer accordion on mobile */
  .footer-column h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 0;
    margin-bottom: 0;
    border-bottom: 1px solid var(--color-border);
  }

  .footer-column h4::after {
    content: '+';
    font-size: 18px;
    font-weight: 300;
    transition: transform var(--transition);
  }

  .footer-column h4.open::after {
    content: '−';
  }

  .footer-column ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-column ul.open {
    max-height: 500px;
    padding: 8px 0;
  }

  .guides-grid {
    grid-template-columns: 1fr;
  }

  .special-stores-grid {
    grid-template-columns: 1fr;
  }

  .product-icon-bar-inner {
    justify-content: flex-start;
    gap: 24px;
    padding: 0 24px;
  }
}

@media (max-width: 480px) {
  .store-hero h1,
  .category-hero h1 {
    font-size: 32px;
  }

  .section-header h2 {
    font-size: 24px;
  }

  .entertainment-content.active {
    grid-template-columns: 1fr;
  }

  .footer-columns {
    grid-template-columns: 1fr;
  }

  .brand-collab h2 {
    font-size: 28px;
  }

  .product-tile h3 {
    font-size: 24px;
  }

  .quick-links-inner {
    flex-direction: column;
    align-items: stretch;
  }

  .quick-link {
    justify-content: center;
  }
}
