/* Orchard — Premium Tech E-Commerce Store */
/* Global Styles */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --color-bg: #ffffff;
  --color-bg-secondary: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-sans: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
  --font-display: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', 'Arial', sans-serif;
  --max-width: 1200px;
  --section-padding: 80px 0;
  --transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1);
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.47059;
  font-size: 17px;
  overflow-x: hidden;
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--color-link-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* ========== RIBBON BANNER ========== */
.ribbon-banner {
  background: #1d1d1f;
  color: #f5f5f7;
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
  line-height: 1.4;
}

.ribbon-banner a {
  color: #2997ff;
  margin-left: 4px;
}

.ribbon-banner a:hover {
  text-decoration: underline;
}

/* ========== TOP NAVIGATION ========== */
.top-nav {
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 1000;
  padding: 0 24px;
}

.top-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 52px;
}

.nav-logo {
  font-size: 21px;
  font-weight: 700;
  color: var(--color-text);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.nav-logo:hover {
  color: var(--color-text);
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: 32px;
  list-style: none;
  align-items: center;
}

.nav-links a {
  font-size: 13px;
  color: var(--color-text);
  text-decoration: none;
  opacity: 0.8;
  transition: opacity var(--transition);
}

.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}

.nav-links a.active {
  opacity: 1;
  font-weight: 600;
}

.nav-hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}

.nav-hamburger span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--color-text);
  margin: 4px 0;
  transition: var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 52px;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(251, 251, 253, 0.98);
  backdrop-filter: blur(20px);
  z-index: 999;
  padding: 32px 24px;
}

.mobile-menu.open {
  display: block;
}

.mobile-menu a {
  display: block;
  font-size: 17px;
  color: var(--color-text);
  padding: 12px 0;
  border-bottom: 1px solid var(--color-border);
  text-decoration: none;
}

/* ========== SECTION UTILITIES ========== */
.section {
  padding: var(--section-padding);
}

.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section-header {
  margin-bottom: 40px;
}

.section-header h2 {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.08;
  color: var(--color-text);
}

.section-header p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 8px;
  font-weight: 400;
}

.section-bg-gray {
  background: var(--color-bg-secondary);
}

/* ========== HERO (Store page) ========== */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg);
}

.store-hero h1 {
  font-family: var(--font-display);
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
  margin-bottom: 12px;
}

.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  font-weight: 400;
  margin-bottom: 24px;
}

.store-hero .hero-links {
  display: flex;
  gap: 24px;
  justify-content: center;
  flex-wrap: wrap;
}

.store-hero .hero-links a {
  font-size: 17px;
  color: var(--color-link);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.store-hero .hero-links a::after {
  content: '›';
  font-size: 20px;
  transition: transform var(--transition);
}

.store-hero .hero-links a:hover::after {
  transform: translateX(2px);
}

/* ========== PRODUCT ICON BAR ========== */
.product-icon-bar {
  padding: 20px 0;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-bg);
}

.product-icon-bar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  justify-content: center;
  gap: 40px;
  overflow-x: auto;
  scrollbar-width: none;
}

.product-icon-bar-inner::-webkit-scrollbar {
  display: none;
}

.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  color: var(--color-text);
  flex-shrink: 0;
  opacity: 0.7;
  transition: opacity var(--transition);
}

.product-icon-item:hover {
  opacity: 1;
  text-decoration: none;
}

.product-icon-item .icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

.product-icon-item span {
  font-size: 12px;
  font-weight: 500;
}

/* ========== CAROUSEL ========== */
.carousel-section {
  padding: 60px 0;
  overflow: hidden;
}

.carousel-header {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 32px;
}

.carousel-header h2 {
  font-family: var(--font-display);
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.1;
}

.carousel-header .carousel-subtitle {
  font-size: 18px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}

.carousel-header .carousel-promo {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-top: 6px;
}

.carousel-nav {
  display: flex;
  gap: 8px;
}

.carousel-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  transition: background var(--transition), opacity var(--transition);
  flex-shrink: 0;
}

.carousel-btn:hover {
  background: var(--color-border);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: default;
}

.carousel-track-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  overflow: visible;
}

.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
  scroll-snap-type: x proximity;
  padding-bottom: 8px;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

/* ========== PRODUCT CARDS (Latest) ========== */
.product-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px 24px;
  text-align: center;
  scroll-snap-align: start;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
  border: 1px solid rgba(0, 0, 0, 0.04);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.08);
}

.product-card .badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  color: #bf4800;
  letter-spacing: 0.02em;
  margin-bottom: 8px;
}

.product-card .badge.new {
  color: #bf4800;
}

.product-card .product-image-placeholder {
  width: 180px;
  height: 180px;
  margin: 0 auto 20px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}

.product-card h3 {
  font-size: 21px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.2;
}

.product-card .tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
  line-height: 1.4;
}

.product-card .price {
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 2px;
}

.product-card .monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* Color variants for product images */
.product-image-placeholder.phone { background: linear-gradient(145deg, #2c2c2e, #1d1d1f); color: #fff; }
.product-image-placeholder.laptop { background: linear-gradient(145deg, #e5e5ea, #c7c7cc); color: #8e8e93; }
.product-image-placeholder.tablet { background: linear-gradient(145deg, #d1d1d6, #aeaeb2); color: #636366; }
.product-image-placeholder.watch { background: linear-gradient(145deg, #1c1c1e, #2c2c2e); color: #48484a; }
.product-image-placeholder.headphones { background: linear-gradient(145deg, #3a3a3c, #1c1c1e); color: #8e8e93; }
.product-image-placeholder.earbuds { background: linear-gradient(145deg, #f2f2f7, #e5e5ea); color: #aeaeb2; }
.product-image-placeholder.speaker { background: linear-gradient(145deg, #2c2c2e, #48484a); color: #8e8e93; }
.product-image-placeholder.accessory { background: linear-gradient(145deg, #ff6b6b, #ee5a24); color: #fff; }
.product-image-placeholder.case { background: linear-gradient(145deg, #ff9ff3, #f368e0); color: #fff; }
.product-image-placeholder.charger { background: linear-gradient(145deg, #f5f5f7, #d2d2d7); color: #8e8e93; }
.product-image-placeholder.keyboard { background: linear-gradient(145deg, #2d3436, #1d1d1f); color: #636366; }
.product-image-placeholder.battery { background: linear-gradient(145deg, #f5f5f7, #e5e5ea); color: #aeaeb2; }
.product-image-placeholder.desktop { background: linear-gradient(145deg, #c7c7cc, #aeaeb2); color: #636366; }
.product-image-placeholder.mini { background: linear-gradient(145deg, #e5e5ea, #d1d1d6); color: #8e8e93; }
.product-image-placeholder.strap { background: linear-gradient(145deg, #ff6b6b, #ff9ff3); color: #fff; }

/* ========== HOMEPAGE PRODUCT GRID ========== */
.product-grid {
  padding: 20px 0 60px;
}

.product-grid-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.product-tile {
  border-radius: 24px;
  padding: 48px 40px 40px;
  min-height: 460px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition);
}

.product-tile:hover {
  transform: scale(1.01);
}

.product-tile-content {
  text-align: center;
  position: relative;
  z-index: 2;
}

.product-tile h3 {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.product-tile .tile-tagline {
  font-size: 18px;
  margin-bottom: 16px;
  line-height: 1.4;
}

.product-tile .tile-ctas {
  display: flex;
  gap: 20px;
  justify-content: center;
}

.product-tile .tile-ctas a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.product-tile .tile-ctas a::after {
  content: '›';
  font-size: 20px;
  transition: transform var(--transition);
}

.product-tile .tile-ctas a:hover::after {
  transform: translateX(3px);
}

.product-tile .tile-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 24px;
  font-size: 72px;
  position: relative;
  z-index: 1;
}

/* Tile color themes */
.tile-dark {
  background: #1d1d1f;
  color: #f5f5f7;
}

.tile-dark .tile-tagline {
  color: #a1a1a6;
}

.tile-dark .tile-ctas a {
  color: #2997ff;
}

.tile-light {
  background: #f5f5f7;
  color: #1d1d1f;
}

.tile-light .tile-tagline {
  color: #6e6e73;
}

.tile-warm {
  background: linear-gradient(135deg, #fdf6ee, #fce8d5);
  color: #1d1d1f;
}

.tile-warm .tile-tagline {
  color: #6e6e73;
}

.tile-cool {
  background: linear-gradient(135deg, #e8f0fe, #d4e4fc);
  color: #1d1d1f;
}

.tile-cool .tile-tagline {
  color: #6e6e73;
}

.tile-green {
  background: linear-gradient(135deg, #e8f5e9, #c8e6c9);
  color: #1d1d1f;
}

.tile-green .tile-tagline {
  color: #4e6e50;
}

.tile-green .tile-ctas a {
  color: #1b5e20;
}

.tile-purple {
  background: linear-gradient(135deg, #f3e5f5, #e1bee7);
  color: #1d1d1f;
}

.tile-purple .tile-tagline {
  color: #6e6e73;
}

/* ========== ENTERTAINMENT TABS ========== */
.entertainment-section {
  padding: 80px 0;
  background: var(--color-bg);
}

.entertainment-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.entertainment-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}

.entertainment-tab {
  padding: 10px 24px;
  border-radius: 980px;
  border: none;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  font-family: var(--font-sans);
}

.entertainment-tab:hover {
  background: var(--color-border);
}

.entertainment-tab.active {
  background: var(--color-text);
  color: var(--color-bg);
}

.entertainment-content {
  display: none;
}

.entertainment-content.active {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.entertainment-card {
  background: var(--color-bg-secondary);
  border-radius: 16px;
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}

.entertainment-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
}

.entertainment-card-visual {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}

.entertainment-card-body {
  padding: 16px;
}

.entertainment-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
}

.entertainment-card-body p {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.entertainment-card-body a {
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.entertainment-card-body a::after {
  content: '›';
  font-size: 16px;
}

/* Entertainment card color themes */
.ent-streaming { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.ent-fitness { background: linear-gradient(135deg, #0f4c3a, #1a6b4f); }
.ent-gaming { background: linear-gradient(135deg, #2d1b69, #4a2c8e); }
.ent-music { background: linear-gradient(135deg, #8e1537, #c0392b); }

/* ========== HELP / SUPPORT CARDS ========== */
.help-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 32px 24px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition), box-shadow var(--transition);
}

.help-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
}

.help-card .help-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 16px;
  background: var(--color-bg-secondary);
}

.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.help-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== STORE DIFFERENCE ========== */
.diff-card {
  flex: 0 0 240px;
  text-align: center;
  padding: 32px 20px;
  background: var(--color-bg);
  border-radius: 20px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition);
}

.diff-card:hover {
  transform: translateY(-2px);
}

.diff-card .diff-icon {
  font-size: 36px;
  margin-bottom: 16px;
}

.diff-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.diff-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== BRAND COLLAB ========== */
.brand-collab {
  padding: 80px 0;
  background: linear-gradient(135deg, #1d1d1f, #2c2c2e);
  color: #f5f5f7;
  text-align: center;
}

.brand-collab h2 {
  font-family: var(--font-display);
  font-size: 40px;
  font-weight: 700;
  margin-bottom: 8px;
}

.brand-collab p {
  font-size: 18px;
  color: #a1a1a6;
  margin-bottom: 24px;
}

.brand-collab .collab-items {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.collab-chip {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 980px;
  padding: 10px 24px;
  font-size: 14px;
  color: #f5f5f7;
}

/* ========== QUICK LINKS ========== */
.quick-links {
  padding: 40px 0;
  background: var(--color-bg);
}

.quick-links-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 12px 24px;
  border-radius: 980px;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  transition: background var(--transition);
}

.quick-link:hover {
  background: var(--color-border);
  text-decoration: none;
  color: var(--color-text);
}

.quick-link::after {
  content: '›';
  font-size: 16px;
  opacity: 0.5;
}

/* ========== CATEGORY PAGE HERO ========== */
.category-hero {
  text-align: center;
  padding: 60px 24px 0;
}

.category-hero h1 {
  font-family: var(--font-display);
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
}

.category-hero .subtitle {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 8px;
}

/* ========== STICKY SECTION NAV ========== */
.section-nav {
  position: sticky;
  top: 52px;
  z-index: 100;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  padding: 0 24px;
  margin-top: 24px;
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: 32px;
  overflow-x: auto;
  scrollbar-width: none;
}

.section-nav-inner::-webkit-scrollbar {
  display: none;
}

.section-nav-link {
  flex-shrink: 0;
  padding: 14px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}

.section-nav-link:hover {
  color: var(--color-text);
  text-decoration: none;
}

.section-nav-link.active {
  color: var(--color-text);
  border-bottom-color: var(--color-text);
}

/* ========== GUIDES / SAVINGS GRID ========== */
.guides-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.guide-card {
  background: var(--color-bg);
  border-radius: 20px;
  padding: 32px 24px;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition), box-shadow var(--transition);
}

.guide-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.06);
}

.guide-card .guide-icon {
  font-size: 32px;
  margin-bottom: 16px;
}

.guide-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.guide-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== FOOTER ========== */
.site-footer {
  background: var(--color-bg-secondary);
  padding: 40px 0 24px;
  border-top: 1px solid var(--color-border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  margin-bottom: 40px;
}

.footer-column h4 {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--color-text);
  cursor: default;
}

.footer-column ul {
  list-style: none;
}

.footer-column li {
  margin-bottom: 6px;
}

.footer-column a {
  font-size: 12px;
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-column a:hover {
  color: var(--color-text);
}

.footer-legal {
  border-top: 1px solid var(--color-border);
  padding-top: 20px;
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.footer-legal p {
  margin-bottom: 8px;
}

.footer-bottom-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 12px;
  flex-wrap: wrap;
  gap: 8px;
}

.footer-bottom-row .copyright {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.footer-bottom-links {
  display: flex;
  gap: 16px;
}

.footer-bottom-links a {
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* ========== SAVINGS CARDS (Carousel) ========== */
.savings-card {
  flex: 0 0 260px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition);
}

.savings-card:hover {
  transform: translateY(-2px);
}

.savings-card .savings-icon {
  font-size: 32px;
  margin-bottom: 16px;
}

.savings-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.savings-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== SPECIAL STORES ========== */
.special-stores-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.special-store-card {
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform var(--transition);
}

.special-store-card:hover { transform: translateY(-2px); }

.special-store-card .store-icon {
  font-size: 28px;
  margin-bottom: 12px;
}

.special-store-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}

.special-store-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .product-grid-inner {
    grid-template-columns: 1fr;
  }

  .entertainment-content.active {
    grid-template-columns: repeat(2, 1fr);
  }

  .section-header h2 {
    font-size: 36px;
  }

  .store-hero h1,
  .category-hero h1 {
    font-size: 44px;
  }

  .carousel-header h2 {
    font-size: 32px;
  }
}

@media (max-width: 768px) {
  body {
    font-size: 15px;
  }

  .nav-links {
    display: none;
  }

  .nav-hamburger {
    display: block;
  }

  .section-header h2 {
    font-size: 28px;
  }

  .section-header p {
    font-size: 17px;
  }

  .store-hero h1,
  .category-hero h1 {
    font-size: 36px;
  }

  .store-hero .subtitle,
  .category-hero .subtitle {
    font-size: 18px;
  }

  .carousel-header h2 {
    font-size: 26px;
  }

  .product-card {
    flex: 0 0 240px;
  }

  .product-tile {
    min-height: 380px;
    padding: 36px 28px 28px;
  }

  .product-tile h3 {
    font-size: 28px;
  }

  .product-tile .tile-tagline {
    font-size: 16px;
  }

  .entertainment-content.active {
    grid-template-columns: 1fr 1fr;
  }

  .footer-columns {
    grid-template-columns: 1fr 1fr;
  }

  /* Footer accordion on mobile */
  .footer-column h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 0;
    margin-bottom: 0;
    border-bottom: 1px solid var(--color-border);
  }

  .footer-column h4::after {
    content: '+';
    font-size: 18px;
    font-weight: 300;
    transition: transform var(--transition);
  }

  .footer-column h4.open::after {
    content: '−';
  }

  .footer-column ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-column ul.open {
    max-height: 500px;
    padding: 8px 0;
  }

  .guides-grid {
    grid-template-columns: 1fr;
  }

  .special-stores-grid {
    grid-template-columns: 1fr;
  }

  .product-icon-bar-inner {
    justify-content: flex-start;
    gap: 24px;
    padding: 0 24px;
  }
}

@media (max-width: 480px) {
  .store-hero h1,
  .category-hero h1 {
    font-size: 32px;
  }

  .section-header h2 {
    font-size: 24px;
  }

  .entertainment-content.active {
    grid-template-columns: 1fr;
  }

  .footer-columns {
    grid-template-columns: 1fr;
  }

  .brand-collab h2 {
    font-size: 28px;
  }

  .product-tile h3 {
    font-size: 24px;
  }

  .quick-links-inner {
    flex-direction: column;
    align-items: stretch;
  }

  .quick-link {
    justify-content: center;
  }
}

/* Orchard — Premium Tech E-Commerce Store */
/* Global Styles */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --color-bg: #ffffff;
  --color-bg-secondary: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-sans: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
  --font-display: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', 'Arial', sans-serif;
  --max-width: 1200px;
  --section-padding: 80px 0;
  --transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1);
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.47059;
  font-size: 17px;
  overflow-x: hidden;
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--color-link-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* ========== RIBBON BANNER ========== */
.ribbon-banner {
  background: #1d1d1f;
  color: #f5f5f7;
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
  line-height: 1.4;
}

.ribbon-banner a {
  color: #2997ff;
  margin-left: 4px;
}

.ribbon-banner a:hover {
  text-decoration: underline;
}

/* ========== TOP NAVIGATION ========== */
.top-nav {
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 1000;
  padding: 0 24px;
}

.top-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 52px;
}

.nav-logo {
  font-size: 21px;
  font-weight: 700;
  color: var(--color-text);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.nav-logo:hover {
  color: var(--color-text);
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: 32px;
  list-style: none;
  align-items: center;
}

.nav-links a {
  font-size: 13px;
  color: var(--color-text);
  text-decoration: none;
  opacity: 0.8;
  transition: opacity var(--transition);
}

.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}

.nav-links a.active {
  opacity: 1;
  font-weight: 600;
}

.nav-hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}

.nav-hamburger span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--color-text);
  margin: 4px 0;
  transition: var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 52px;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(251, 251, 253, 0.98);
  backdrop-filter: blur(20px);
  z-index: 999;
  padding: 32px 24px;
}

.mobile-menu.open {
  display: block;
}

.mobile-menu a {
  display: block;
  font-size: 17px;
  color: var(--color-text);
  padding: 12px 0;
  border-bottom: 1px solid var(--color-border);
  text-decoration: none;
}

/* ========== SECTION UTILITIES ========== */
.section {
  padding: var(--section-padding);
}

.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section-header {
  margin-bottom: 40px;
}

.section-header h2 {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.08;
  color: var(--color-text);
}

.section-header p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 8px;
  font-weight: 400;
}

.section-bg-gray {
  background: var(--color-bg-secondary);
}

/* ========== HERO (Store page) ========== */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg);
}

.store-hero h1 {
  font-family: var(--font-display);
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
  margin-bottom: 12px;
}

.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  font-weight: 400;
  margin-bottom: 24px;
}

.store-hero .hero-links {
  display: flex;
  gap: 24px;
  justify-content: center;
  flex-wrap: wrap;
}

.store-hero .hero-links a {
  font-size: 17px;
  color: var(--color-link);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.store-hero .hero-links a::after {
  content: '›';
  font-size: 20px;
  transition: transform var(--transition);
}

.store-hero .hero-links a:hover::after {
  transform: translateX(2px);
}

/* ========== PRODUCT ICON BAR ========== */
.product-icon-bar {
  padding: 20px 0;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-bg);
}

.product-icon-bar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  justify-content: center;
  gap: 40px;
  overflow-x: auto;
  scrollbar-width: none;
}

.product-icon-bar-inner::-webkit-scrollbar {
  display: none;
}

.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  color: var(--color-text);
  flex-shrink: 0;
  opacity: 0.7;
  transition: opacity var(--transition);
}

.product-icon-item:hover {
  opacity: 1;
  text-decoration: none;
}

.product-icon-item .icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

.product-icon-item span {
  font-size: 12px;
  font-weight: 500;
}

/* ========== CAROUSEL ========== */
.carousel-section {
  padding: 60px 0;
  overflow: hidden;
}

.carousel-header {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 32px;
}

.carousel-header h2 {
  font-family: var(--font-display);
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.1;
}

.carousel-header .carousel-subtitle {
  font-size: 18px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}

.carousel-header .carousel-promo {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-top: 6px;
}

.carousel-nav {
  display: flex;
  gap: 8px;
}

.carousel-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  transition: background var(--transition), opacity var(--transition);
  flex-shrink: 0;
}

.carousel-btn:hover {
  background: var(--color-border);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: default;
}

.carousel-track-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  overflow: visible;
}

.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
  scroll-snap-type: x proximity;
  padding-bottom: 8px;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

/* ========== PRODUCT CARDS (Latest) ========== */
.product-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px 24px;
  text-align: center;
  scroll-snap-align: start;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
  border: 1px solid rgba(0, 0, 0, 0.04);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.08);
}

.product-card .badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  color: #bf4800;
  letter-spacing: 0.02em;
  margin-bottom: 8px;
}

.product-card .badge.new {
  color: #bf4800;
}

.product-card .product-image-placeholder {
  width: 180px;
  height: 180px;
  margin: 0 auto 20px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}

.product-card h3 {
  font-size: 21px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.2;
}

.product-card .tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
  line-height: 1.4;
}

.product-card .price {
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 2px;
}

.product-card .monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* Color variants for product images */
.product-image-placeholder.phone { background: linear-gradient(145deg, #2c2c2e, #1d1d1f); color: #fff; }
.product-image-placeholder.laptop { background: linear-gradient(145deg, #e5e5ea, #c7c7cc); color: #8e8e93; }
.product-image-placeholder.tablet { background: linear-gradient(145deg, #d1d1d6, #aeaeb2); color: #636366; }
.product-image-placeholder.watch { background: linear-gradient(145deg, #1c1c1e, #2c2c2e); color: #48484a; }
.product-image-placeholder.headphones { background: linear-gradient(145deg, #3a3a3c, #1c1c1e); color: #8e8e93; }
.product-image-placeholder.earbuds { background: linear-gradient(145deg, #f2f2f7, #e5e5ea); color: #aeaeb2; }
.product-image-placeholder.speaker { background: linear-gradient(145deg, #2c2c2e, #48484a); color: #8e8e93; }
.product-image-placeholder.accessory { background: linear-gradient(145deg, #ff6b6b, #ee5a24); color: #fff; }
.product-image-placeholder.case { background: linear-gradient(145deg, #ff9ff3, #f368e0); color: #fff; }
.product-image-placeholder.charger { background: linear-gradient(145deg, #f5f5f7, #d2d2d7); color: #8e8e93; }
.product-image-placeholder.keyboard { background: linear-gradient(145deg, #2d3436, #1d1d1f); color: #636366; }
.product-image-placeholder.battery { background: linear-gradient(145deg, #f5f5f7, #e5e5ea); color: #aeaeb2; }
.product-image-placeholder.desktop { background: linear-gradient(145deg, #c7c7cc, #aeaeb2); color: #636366; }
.product-image-placeholder.mini { background: linear-gradient(145deg, #e5e5ea, #d1d1d6); color: #8e8e93; }
.product-image-placeholder.strap { background: linear-gradient(145deg, #ff6b6b, #ff9ff3); color: #fff; }

/* ========== HOMEPAGE PRODUCT GRID ========== */
.product-grid {
  padding: 20px 0 60px;
}

.product-grid-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.product-tile {
  border-radius: 24px;
  padding: 48px 40px 40px;
  min-height: 460px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition);
}

.product-tile:hover {
  transform: scale(1.01);
}

.product-tile-content {
  text-align: center;
  position: relative;
  z-index: 2;
}

.product-tile h3 {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.product-tile .tile-tagline {
  font-size: 18px;
  margin-bottom: 16px;
  line-height: 1.4;
}

.product-tile .tile-ctas {
  display: flex;
  gap: 20px;
  justify-content: center;
}

.product-tile .tile-ctas a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.product-tile .tile-ctas a::after {
  content: '›';
  font-size: 20px;
  transition: transform var(--transition);
}

.product-tile .tile-ctas a:hover::after {
  transform: translateX(3px);
}

.product-tile .tile-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 24px;
  font-size: 72px;
  position: relative;
  z-index: 1;
}

/* Tile color themes */
.tile-dark {
  background: #1d1d1f;
  color: #f5f5f7;
}

.tile-dark .tile-tagline {
  color: #a1a1a6;
}

.tile-dark .tile-ctas a {
  color: #2997ff;
}

.tile-light {
  background: #f5f5f7;
  color: #1d1d1f;
}

.tile-light .tile-tagline {
  color: #6e6e73;
}

.tile-warm {
  background: linear-gradient(135deg, #fdf6ee, #fce8d5);
  color: #1d1d1f;
}

.tile-warm .tile-tagline {
  color: #6e6e73;
}

.tile-cool {
  background: linear-gradient(135deg, #e8f0fe, #d4e4fc);
  color: #1d1d1f;
}

.tile-cool .tile-tagline {
  color: #6e6e73;
}

.tile-green {
  background: linear-gradient(135deg, #e8f5e9, #c8e6c9);
  color: #1d1d1f;
}

.tile-green .tile-tagline {
  color: #4e6e50;
}

.tile-green .tile-ctas a {
  color: #1b5e20;
}

.tile-purple {
  background: linear-gradient(135deg, #f3e5f5, #e1bee7);
  color: #1d1d1f;
}

.tile-purple .tile-tagline {
  color: #6e6e73;
}

/* ========== ENTERTAINMENT TABS ========== */
.entertainment-section {
  padding: 80px 0;
  background: var(--color-bg);
}

.entertainment-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.entertainment-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}

.entertainment-tab {
  padding: 10px 24px;
  border-radius: 980px;
  border: none;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  font-family: var(--font-sans);
}

.entertainment-tab:hover {
  background: var(--color-border);
}

.entertainment-tab.active {
  background: var(--color-text);
  color: var(--color-bg);
}

.entertainment-content {
  display: none;
}

.entertainment-content.active {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.entertainment-card {
  background: var(--color-bg-secondary);
  border-radius: 16px;
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}

.entertainment-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
}

.entertainment-card-visual {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}

.entertainment-card-body {
  padding: 16px;
}

.entertainment-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
}

.entertainment-card-body p {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.entertainment-card-body a {
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.entertainment-card-body a::after {
  content: '›';
  font-size: 16px;
}

/* Entertainment card color themes */
.ent-streaming { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.ent-fitness { background: linear-gradient(135deg, #0f4c3a, #1a6b4f); }
.ent-gaming { background: linear-gradient(135deg, #2d1b69, #4a2c8e); }
.ent-music { background: linear-gradient(135deg, #8e1537, #c0392b); }

/* ========== HELP / SUPPORT CARDS ========== */
.help-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 32px 24px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition), box-shadow var(--transition);
}

.help-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
}

.help-card .help-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 16px;
  background: var(--color-bg-secondary);
}

.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.help-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== STORE DIFFERENCE ========== */
.diff-card {
  flex: 0 0 240px;
  text-align: center;
  padding: 32px 20px;
  background: var(--color-bg);
  border-radius: 20px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition);
}

.diff-card:hover {
  transform: translateY(-2px);
}

.diff-card .diff-icon {
  font-size: 36px;
  margin-bottom: 16px;
}

.diff-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.diff-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== BRAND COLLAB ========== */
.brand-collab {
  padding: 80px 0;
  background: linear-gradient(135deg, #1d1d1f, #2c2c2e);
  color: #f5f5f7;
  text-align: center;
}

.brand-collab h2 {
  font-family: var(--font-display);
  font-size: 40px;
  font-weight: 700;
  margin-bottom: 8px;
}

.brand-collab p {
  font-size: 18px;
  color: #a1a1a6;
  margin-bottom: 24px;
}

.brand-collab .collab-items {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.collab-chip {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 980px;
  padding: 10px 24px;
  font-size: 14px;
  color: #f5f5f7;
}

/* ========== QUICK LINKS ========== */
.quick-links {
  padding: 40px 0;
  background: var(--color-bg);
}

.quick-links-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 12px 24px;
  border-radius: 980px;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  transition: background var(--transition);
}

.quick-link:hover {
  background: var(--color-border);
  text-decoration: none;
  color: var(--color-text);
}

.quick-link::after {
  content: '›';
  font-size: 16px;
  opacity: 0.5;
}

/* ========== CATEGORY PAGE HERO ========== */
.category-hero {
  text-align: center;
  padding: 60px 24px 0;
}

.category-hero h1 {
  font-family: var(--font-display);
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
}

.category-hero .subtitle {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 8px;
}

/* ========== STICKY SECTION NAV ========== */
.section-nav {
  position: sticky;
  top: 52px;
  z-index: 100;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  padding: 0 24px;
  margin-top: 24px;
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: 32px;
  overflow-x: auto;
  scrollbar-width: none;
}

.section-nav-inner::-webkit-scrollbar {
  display: none;
}

.section-nav-link {
  flex-shrink: 0;
  padding: 14px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}

.section-nav-link:hover {
  color: var(--color-text);
  text-decoration: none;
}

.section-nav-link.active {
  color: var(--color-text);
  border-bottom-color: var(--color-text);
}

/* ========== GUIDES / SAVINGS GRID ========== */
.guides-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.guide-card {
  background: var(--color-bg);
  border-radius: 20px;
  padding: 32px 24px;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition), box-shadow var(--transition);
}

.guide-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.06);
}

.guide-card .guide-icon {
  font-size: 32px;
  margin-bottom: 16px;
}

.guide-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.guide-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== FOOTER ========== */
.site-footer {
  background: var(--color-bg-secondary);
  padding: 40px 0 24px;
  border-top: 1px solid var(--color-border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  margin-bottom: 40px;
}

.footer-column h4 {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--color-text);
  cursor: default;
}

.footer-column ul {
  list-style: none;
}

.footer-column li {
  margin-bottom: 6px;
}

.footer-column a {
  font-size: 12px;
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-column a:hover {
  color: var(--color-text);
}

.footer-legal {
  border-top: 1px solid var(--color-border);
  padding-top: 20px;
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.footer-legal p {
  margin-bottom: 8px;
}

.footer-bottom-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 12px;
  flex-wrap: wrap;
  gap: 8px;
}

.footer-bottom-row .copyright {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.footer-bottom-links {
  display: flex;
  gap: 16px;
}

.footer-bottom-links a {
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* ========== SAVINGS CARDS (Carousel) ========== */
.savings-card {
  flex: 0 0 260px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition);
}

.savings-card:hover {
  transform: translateY(-2px);
}

.savings-card .savings-icon {
  font-size: 32px;
  margin-bottom: 16px;
}

.savings-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.savings-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== SPECIAL STORES ========== */
.special-stores-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.special-store-card {
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform var(--transition);
}

.special-store-card:hover { transform: translateY(-2px); }

.special-store-card .store-icon {
  font-size: 28px;
  margin-bottom: 12px;
}

.special-store-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}

.special-store-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .product-grid-inner {
    grid-template-columns: 1fr;
  }

  .entertainment-content.active {
    grid-template-columns: repeat(2, 1fr);
  }

  .section-header h2 {
    font-size: 36px;
  }

  .store-hero h1,
  .category-hero h1 {
    font-size: 44px;
  }

  .carousel-header h2 {
    font-size: 32px;
  }
}

@media (max-width: 768px) {
  body {
    font-size: 15px;
  }

  .nav-links {
    display: none;
  }

  .nav-hamburger {
    display: block;
  }

  .section-header h2 {
    font-size: 28px;
  }

  .section-header p {
    font-size: 17px;
  }

  .store-hero h1,
  .category-hero h1 {
    font-size: 36px;
  }

  .store-hero .subtitle,
  .category-hero .subtitle {
    font-size: 18px;
  }

  .carousel-header h2 {
    font-size: 26px;
  }

  .product-card {
    flex: 0 0 240px;
  }

  .product-tile {
    min-height: 380px;
    padding: 36px 28px 28px;
  }

  .product-tile h3 {
    font-size: 28px;
  }

  .product-tile .tile-tagline {
    font-size: 16px;
  }

  .entertainment-content.active {
    grid-template-columns: 1fr 1fr;
  }

  .footer-columns {
    grid-template-columns: 1fr 1fr;
  }

  /* Footer accordion on mobile */
  .footer-column h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 0;
    margin-bottom: 0;
    border-bottom: 1px solid var(--color-border);
  }

  .footer-column h4::after {
    content: '+';
    font-size: 18px;
    font-weight: 300;
    transition: transform var(--transition);
  }

  .footer-column h4.open::after {
    content: '−';
  }

  .footer-column ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-column ul.open {
    max-height: 500px;
    padding: 8px 0;
  }

  .guides-grid {
    grid-template-columns: 1fr;
  }

  .special-stores-grid {
    grid-template-columns: 1fr;
  }

  .product-icon-bar-inner {
    justify-content: flex-start;
    gap: 24px;
    padding: 0 24px;
  }
}

@media (max-width: 480px) {
  .store-hero h1,
  .category-hero h1 {
    font-size: 32px;
  }

  .section-header h2 {
    font-size: 24px;
  }

  .entertainment-content.active {
    grid-template-columns: 1fr;
  }

  .footer-columns {
    grid-template-columns: 1fr;
  }

  .brand-collab h2 {
    font-size: 28px;
  }

  .product-tile h3 {
    font-size: 24px;
  }

  .quick-links-inner {
    flex-direction: column;
    align-items: stretch;
  }

  .quick-link {
    justify-content: center;
  }
}

raw_arguments.content:
/* Orchard — Premium Tech E-Commerce Store */
/* Global Styles */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --color-bg: #ffffff;
  --color-bg-secondary: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-sans: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
  --font-display: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', 'Arial', sans-serif;
  --max-width: 1200px;
  --section-padding: 80px 0;
  --transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1);
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.47059;
  font-size: 17px;
  overflow-x: hidden;
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--color-link-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* ========== RIBBON BANNER ========== */
.ribbon-banner {
  background: #1d1d1f;
  color: #f5f5f7;
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
  line-height: 1.4;
}

.ribbon-banner a {
  color: #2997ff;
  margin-left: 4px;
}

.ribbon-banner a:hover {
  text-decoration: underline;
}

/* ========== TOP NAVIGATION ========== */
.top-nav {
  background: rgba(251, 251, 253, 0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 1000;
  padding: 0 24px;
}

.top-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 52px;
}

.nav-logo {
  font-size: 21px;
  font-weight: 700;
  color: var(--color-text);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.nav-logo:hover {
  color: var(--color-text);
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: 32px;
  list-style: none;
  align-items: center;
}

.nav-links a {
  font-size: 13px;
  color: var(--color-text);
  text-decoration: none;
  opacity: 0.8;
  transition: opacity var(--transition);
}

.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}

.nav-links a.active {
  opacity: 1;
  font-weight: 600;
}

.nav-hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}

.nav-hamburger span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--color-text);
  margin: 4px 0;
  transition: var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 52px;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(251, 251, 253, 0.98);
  backdrop-filter: blur(20px);
  z-index: 999;
  padding: 32px 24px;
}

.mobile-menu.open {
  display: block;
}

.mobile-menu a {
  display: block;
  font-size: 17px;
  color: var(--color-text);
  padding: 12px 0;
  border-bottom: 1px solid var(--color-border);
  text-decoration: none;
}

/* ========== SECTION UTILITIES ========== */
.section {
  padding: var(--section-padding);
}

.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section-header {
  margin-bottom: 40px;
}

.section-header h2 {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.08;
  color: var(--color-text);
}

.section-header p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 8px;
  font-weight: 400;
}

.section-bg-gray {
  background: var(--color-bg-secondary);
}

/* ========== HERO (Store page) ========== */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg);
}

.store-hero h1 {
  font-family: var(--font-display);
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
  margin-bottom: 12px;
}

.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  font-weight: 400;
  margin-bottom: 24px;
}

.store-hero .hero-links {
  display: flex;
  gap: 24px;
  justify-content: center;
  flex-wrap: wrap;
}

.store-hero .hero-links a {
  font-size: 17px;
  color: var(--color-link);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.store-hero .hero-links a::after {
  content: '›';
  font-size: 20px;
  transition: transform var(--transition);
}

.store-hero .hero-links a:hover::after {
  transform: translateX(2px);
}

/* ========== PRODUCT ICON BAR ========== */
.product-icon-bar {
  padding: 20px 0;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-bg);
}

.product-icon-bar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  justify-content: center;
  gap: 40px;
  overflow-x: auto;
  scrollbar-width: none;
}

.product-icon-bar-inner::-webkit-scrollbar {
  display: none;
}

.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  color: var(--color-text);
  flex-shrink: 0;
  opacity: 0.7;
  transition: opacity var(--transition);
}

.product-icon-item:hover {
  opacity: 1;
  text-decoration: none;
}

.product-icon-item .icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

.product-icon-item span {
  font-size: 12px;
  font-weight: 500;
}

/* ========== CAROUSEL ========== */
.carousel-section {
  padding: 60px 0;
  overflow: hidden;
}

.carousel-header {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 32px;
}

.carousel-header h2 {
  font-family: var(--font-display);
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.1;
}

.carousel-header .carousel-subtitle {
  font-size: 18px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}

.carousel-header .carousel-promo {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-top: 6px;
}

.carousel-nav {
  display: flex;
  gap: 8px;
}

.carousel-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  transition: background var(--transition), opacity var(--transition);
  flex-shrink: 0;
}

.carousel-btn:hover {
  background: var(--color-border);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: default;
}

.carousel-track-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  overflow: visible;
}

.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
  scroll-snap-type: x proximity;
  padding-bottom: 8px;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

/* ========== PRODUCT CARDS (Latest) ========== */
.product-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px 24px;
  text-align: center;
  scroll-snap-align: start;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
  border: 1px solid rgba(0, 0, 0, 0.04);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.08);
}

.product-card .badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  color: #bf4800;
  letter-spacing: 0.02em;
  margin-bottom: 8px;
}

.product-card .badge.new {
  color: #bf4800;
}

.product-card .product-image-placeholder {
  width: 180px;
  height: 180px;
  margin: 0 auto 20px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}

.product-card h3 {
  font-size: 21px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.2;
}

.product-card .tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
  line-height: 1.4;
}

.product-card .price {
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 2px;
}

.product-card .monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
}

/* Color variants for product images */
.product-image-placeholder.phone { background: linear-gradient(145deg, #2c2c2e, #1d1d1f); color: #fff; }
.product-image-placeholder.laptop { background: linear-gradient(145deg, #e5e5ea, #c7c7cc); color: #8e8e93; }
.product-image-placeholder.tablet { background: linear-gradient(145deg, #d1d1d6, #aeaeb2); color: #636366; }
.product-image-placeholder.watch { background: linear-gradient(145deg, #1c1c1e, #2c2c2e); color: #48484a; }
.product-image-placeholder.headphones { background: linear-gradient(145deg, #3a3a3c, #1c1c1e); color: #8e8e93; }
.product-image-placeholder.earbuds { background: linear-gradient(145deg, #f2f2f7, #e5e5ea); color: #aeaeb2; }
.product-image-placeholder.speaker { background: linear-gradient(145deg, #2c2c2e, #48484a); color: #8e8e93; }
.product-image-placeholder.accessory { background: linear-gradient(145deg, #ff6b6b, #ee5a24); color: #fff; }
.product-image-placeholder.case { background: linear-gradient(145deg, #ff9ff3, #f368e0); color: #fff; }
.product-image-placeholder.charger { background: linear-gradient(145deg, #f5f5f7, #d2d2d7); color: #8e8e93; }
.product-image-placeholder.keyboard { background: linear-gradient(145deg, #2d3436, #1d1d1f); color: #636366; }
.product-image-placeholder.battery { background: linear-gradient(145deg, #f5f5f7, #e5e5ea); color: #aeaeb2; }
.product-image-placeholder.desktop { background: linear-gradient(145deg, #c7c7cc, #aeaeb2); color: #636366; }
.product-image-placeholder.mini { background: linear-gradient(145deg, #e5e5ea, #d1d1d6); color: #8e8e93; }
.product-image-placeholder.strap { background: linear-gradient(145deg, #ff6b6b, #ff9ff3); color: #fff; }

/* ========== HOMEPAGE PRODUCT GRID ========== */
.product-grid {
  padding: 20px 0 60px;
}

.product-grid-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.product-tile {
  border-radius: 24px;
  padding: 48px 40px 40px;
  min-height: 460px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition);
}

.product-tile:hover {
  transform: scale(1.01);
}

.product-tile-content {
  text-align: center;
  position: relative;
  z-index: 2;
}

.product-tile h3 {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.product-tile .tile-tagline {
  font-size: 18px;
  margin-bottom: 16px;
  line-height: 1.4;
}

.product-tile .tile-ctas {
  display: flex;
  gap: 20px;
  justify-content: center;
}

.product-tile .tile-ctas a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.product-tile .tile-ctas a::after {
  content: '›';
  font-size: 20px;
  transition: transform var(--transition);
}

.product-tile .tile-ctas a:hover::after {
  transform: translateX(3px);
}

.product-tile .tile-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 24px;
  font-size: 72px;
  position: relative;
  z-index: 1;
}

