@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.entertainment-card {
  background: var(--color-bg-secondary);
  border-radius: 16px;
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}

.entertainment-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
}

.entertainment-card-visual {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}

.entertainment-card-body {
  padding: 16px;
}

.entertainment-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
}

.entertainment-card-body p {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.entertainment-card-body a {
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.entertainment-card-body a::after {
  content: '›';
  font-size: 16px;
}

/* Entertainment card color themes */
.ent-streaming { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.ent-fitness { background: linear-gradient(135deg, #0f4c3a, #1a6b4f); }
.ent-gaming { background: linear-gradient(135deg, #2d1b69, #4a2c8e); }
.ent-music { background: linear-gradient(135deg, #8e1537, #c0392b); }

/* ========== HELP / SUPPORT CARDS ========== */
.help-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 32px 24px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition), box-shadow var(--transition);
}

.help-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
}

.help-card .help-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 16px;
  background: var(--color-bg-secondary);
}

.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.help-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== STORE DIFFERENCE ========== */
.diff-card {
  flex: 0 0 240px;
  text-align: center;
  padding: 32px 20px;
  background: var(--color-bg);
  border-radius: 20px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition);
}

.diff-card:hover {
  transform: translateY(-2px);
}

.diff-card .diff-icon {
  font-size: 36px;
  margin-bottom: 16px;
}

.diff-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.diff-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
