.brand-collab h2 {
  font-family: var(--font-display);
  font-size: 40px;
  font-weight: 700;
  margin-bottom: 8px;
}

.brand-collab p {
  font-size: 18px;
  color: #a1a1a6;
  margin-bottom: 24px;
}

.brand-collab .collab-items {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.collab-chip {
  background: rgba(255, 255, 255, 0.1);
