.footer-bottom-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 12px;
  flex-wrap: wrap;
  gap: 8px;
}

.footer-bottom-row .copyright {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.footer-bottom-links {
  display: flex;
  gap: 16px;
}

.footer-bottom-links a {
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* ========== SAVINGS CARDS (Carousel) ========== */
.savings-card {
  flex: 0 0 260px;
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px;
  scroll-snap-align: start;
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: transform var(--transition);
}

.savings-card:hover {
  transform: translateY(-2px);
}

.savings-card .savings-icon {
  font-size: 32px;
  margin-bottom: 16px;
}

.savings-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.savings-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== SPECIAL STORES ========== */
.special-stores-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.special-store-card {
  background: var(--color-bg);
  border-radius: 20px;
  padding: 28px 24px;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform var(--transition);
}

.special-store-card:hover { transform: translateY(-2px); }

.special-store-card .store-icon {
  font-size: 28px;
  margin-bottom: 12px;
}

.special-store-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}

.special-store-card p {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .product-grid-inner {
    grid-template-columns: 1fr;
  }

  .entertainment-content.active {
    grid-template-columns: repeat(2, 1fr);
  }

  .section-header h2 {
    font-size: 36px;
  }

  .store-hero h1,
  .category-hero h1 {
    font-size: 44px;
  }

  .carousel-header h2 {
    font-size: 32px;
  }
}

@media (max-width: 768px) {
  body {
    font-size: 15px;
  }

  .nav-links {
    display: none;
  }

  .nav-hamburger {
    display: block;
  }

  .section-header h2 {
    font-size: 28px;
  }

  .section-header p {
    font-size: 17px;
  }

  .store-hero h1,
  .category-hero h1 {
    font-size: 36px;
  }

  .store-hero .subtitle,
  .category-hero .subtitle {
    font-size: 18px;
  }

  .carousel-header h2 {
    font-size: 26px;
  }

  .product-card {
    flex: 0 0 240px;
  }

  .product-tile {
    min-height: 380px;
    padding: 36px 28px 28px;
  }

  .product-tile h3 {
    font-size: 28px;
  }

  .product-tile .tile-tagline {
    font-size: 16px;
  }

  .entertainment-content.active {
    grid-template-columns: 1fr 1fr;
  }

  .footer-columns {
    grid-template-columns: 1fr 1fr;
  }

  /* Footer accordion on mobile */
  .footer-column h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 0;
    margin-bottom: 0;
    border-bottom: 1px solid var(--color-border);
  }

  .footer-column h4::after {
    content: '+';
    font-size: 18px;
    font-weight: 300;
    transition: transform var(--transition);
  }

  .footer-column h4.open::after {
    content: '−';
  }

  .footer-column ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-column ul.open {
    max-height: 500px;
    padding: 8px 0;
  }

  .guides-grid {
    grid-template-columns: 1fr;
  }

  .special-stores-grid {
    grid-template-columns: 1fr;
  }

  .product-icon-bar-inner {
    justify-content: flex-start;
    gap: 24px;
    padding: 0 24px;
  }
}

@media (max-width: 480px) {
  .store-hero h1,
  .category-hero h1 {
    font-size: 32px;
  }

  .section-header h2 {
    font-size: 24px;
  }

  .entertainment-content.active {
    grid-template-columns: 1fr;
  }

  .footer-columns {
    grid-template-columns: 1fr;
  }

  .brand-collab h2 {
    font-size: 28px;
  }

  .product-tile h3 {
    font-size: 24px;
  }

  .quick-links-inner {
    flex-direction: column;
    align-items: stretch;
  }

  .quick-link {
    justify-content: center;
  }
}

